<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Service extends Model {protected $guarded=[]; protected $casts=['active'=>'boolean','base_price'=>'decimal:2','labor_cost'=>'decimal:2','tax_rate'=>'decimal:2']; public function category(){return $this->belongsTo(ServiceCategory::class,'service_category_id');} public function jobServices(){return $this->hasMany(JobService::class);} public function business(){return $this->belongsTo(Business::class);}}
